+import Foundation
+import ApplicationServices
+
+func attr(_ element: AXUIElement, _ name: CFString) -> AnyObject? {
+    var value: CFTypeRef?
+    let err = AXUIElementCopyAttributeValue(element, name, &value)
+    if err != .success { return nil }
+    return value
+}
+
+func stringAttr(_ element: AXUIElement, _ name: CFString) -> String? {
+    attr(element, name) as? String
+}
+
+func role(_ element: AXUIElement) -> String { stringAttr(element, kAXRoleAttribute) ?? "?" }
+func title(_ element: AXUIElement) -> String? { stringAttr(element, kAXTitleAttribute) }
+func desc(_ element: AXUIElement) -> String? { stringAttr(element, kAXDescriptionAttribute) }
+func identifier(_ element: AXUIElement) -> String? { stringAttr(element, kAXIdentifierAttribute) }
+
+func children(of element: AXUIElement) -> [AXUIElement] {
+    guard let value = attr(element, kAXChildrenAttribute) as? [AXUIElement] else { return [] }
+    return value
+}
+
+func dump(_ element: AXUIElement, depth: Int = 0, maxDepth: Int = 6) {
+    let indent = String(repeating: "  ", count: depth)
+    let pieces = [role(element), title(element), desc(element), identifier(element)].compactMap { $0 }.filter { !$0.isEmpty }
+    if !pieces.isEmpty {
+        print(indent + pieces.joined(separator: " | "))
+    }
+    guard depth < maxDepth else { return }
+    for child in children(of: element) {
+        dump(child, depth: depth + 1, maxDepth: maxDepth)
+    }
+}
+
+guard CommandLine.arguments.count > 1, let pid = pid_t(CommandLine.arguments[1]) else {
+    fputs("usage: axdump <pid>\n", stderr)
+    exit(2)
+}
+
+let app = AXUIElementCreateApplication(pid)
+dump(app)
*** End Patch

