+import Foundation
+import ApplicationServices
+
+func attr(_ element: AXUIElement, _ name: String) -> AnyObject? {
+    var value: CFTypeRef?
+    let err = AXUIElementCopyAttributeValue(element, name as CFString, &value)
+    if err != .success { return nil }
+    return value
+}
+
+func stringAttr(_ element: AXUIElement, _ name: String) -> String? {
+    attr(element, name) as? String
+}
+
+func children(of element: AXUIElement) -> [AXUIElement] {
+    guard let value = attr(element, kAXChildrenAttribute as String) as? [AXUIElement] else { return [] }
+    return value
+}
+
+func matches(_ element: AXUIElement, needle: String) -> Bool {
+    let fields = [
+        stringAttr(element, kAXIdentifierAttribute as String),
+        stringAttr(element, kAXTitleAttribute as String),
+        stringAttr(element, kAXDescriptionAttribute as String),
+    ].compactMap { $0 }
+    return fields.contains { $0 == needle || $0.contains(needle) }
+}
+
+func find(_ element: AXUIElement, needle: String) -> AXUIElement? {
+    if matches(element, needle: needle) { return element }
+    for child in children(of: element) {
+        if let found = find(child, needle: needle) { return found }
+    }
+    return nil
+}
+
+guard CommandLine.arguments.count > 2, let pid = pid_t(CommandLine.arguments[1]) else {
+    fputs("usage: axpress <pid> <needle>\n", stderr)
+    exit(2)
+}
+
+let needle = CommandLine.arguments[2]
+let app = AXUIElementCreateApplication(pid)
+guard let element = find(app, needle: needle) else {
+    fputs("not found: \(needle)\n", stderr)
+    exit(1)
+}
+
+let title = stringAttr(element, kAXTitleAttribute as String) ?? ""
+let identifier = stringAttr(element, kAXIdentifierAttribute as String) ?? ""
+print("found: title=\(title) id=\(identifier)")
+let err = AXUIElementPerformAction(element, kAXPressAction as CFString)
+print("press: \(err.rawValue)")
*** End Patch

